    private static JsonElement Suite() => JsonDocument.Parse(File.ReadAllText(SuitePath)).RootElement;

    private static JsonElement Vector(string id) =>
        Suite().GetProperty("vectors").EnumerateArray().Single(v => v.GetProperty("id").GetString() == id);

    public static IEnumerable<object[]> VectorIds() => Suite().GetProperty("vectors").EnumerateArray()
        .Where(v => KindsRun.Contains(v.GetProperty("kind").GetString()!))
        .Select(v => new object[] { v.GetProperty("id").GetString()! });

    internal static ConformanceReceipt Receipt() => ConformanceReceipts.For(
        "out_of_band", typeof(OutOfBandTests), nameof(ReproducesTheReferenceOutcome), VectorIds(), KindsRun, KindsNotRun);

    [Fact]
    public void EveryKindIsRunOrListedAsNotRun() => ConformanceReceipts.Record(Receipt());

    [Theory]
    [MemberData(nameof(VectorIds))]
    public void ReproducesTheReferenceOutcome(string id)
    {
        var v = Vector(id);
        var expected = v.GetProperty("expected");
        var kind = v.GetProperty("kind").GetString();
        if (kind == "verify_export")
        {
            VerifiesTheExport(v.GetProperty("input"), expected);
            return;
        }
        var record = v.GetProperty("record").GetRawText();
        switch (kind)
        {
            case "canonical_form":
                Assert.Equal(expected.GetProperty("canonical").GetString(), OfflineVerifier.OutOfBandCanonical(record));
                Assert.Equal(expected.GetProperty("digest").GetString(), OfflineVerifier.OutOfBandDigest(record));
                break;
            case "verify_record":
                Assert.Equal(expected.GetProperty("valid").GetBoolean(),
                    OfflineVerifier.VerifyOutOfBandRecord(record, [v.GetProperty("public_key").GetString()!]));
                break;
            default:
                var problem = v.GetProperty("record_kind").GetString() == "observation"
                    ? EvidenceMetadata.ObservationProblem(JsonSerializer.Deserialize<ObservationRecord>(record)!)
                    : EvidenceMetadata.BreakGlassProblem(JsonSerializer.Deserialize<BreakGlassRecord>(record)!);
                var want = expected.GetProperty("problem");
                Assert.Equal(want.ValueKind == JsonValueKind.Null ? null : want.GetString(), problem);
                break;
        }
    }

    /// <summary>
    /// A <c>verify_export</c> vector (the out-of-band and remediation suites): the failures in order, whether it verified,
    /// and the counts of the kinds it holds.
    /// </summary>
    internal static void VerifiesTheExport(JsonElement input, JsonElement expected)
    {
        var r = OfflineVerifier.VerifyEvidenceEvents(OfflineVerifier.ParseExportLines(input.GetProperty("lines").GetString()!),
            new EvidenceVerifyOptions
            {
                NAPublicKeys = input.GetProperty("na_public_keys").EnumerateArray().Select(k => k.GetString()!).ToList(),
                ExecutorKeys = input.GetProperty("executor_keys").Deserialize<List<ExecutorKeyRecord>>()!,
                Contiguous = input.GetProperty("contiguous").GetBoolean(),
                Checkpoint = input.TryGetProperty("checkpoint", out var checkpoint) ? checkpoint.GetRawText() : null,
            });
        static long? Position(JsonElement f) =>
            f.GetProperty("store_sequence").ValueKind == JsonValueKind.Null ? null : f.GetProperty("store_sequence").GetInt64();
        Assert.Equal(expected.GetProperty("failures").EnumerateArray().Select(f => (Position(f), f.GetProperty("reason").GetString()!)),
            r.Failures.Select(f => (f.StoreSequence, f.Reason)));
        Assert.Equal(expected.GetProperty("verified").GetBoolean(), r.Verified);
        var counts = new Dictionary<string, long>
        {
            ["observations"] = r.Observations,
            ["break_glass"] = r.BreakGlass,
            ["judgements"] = r.Judgements,
            ["quarantined"] = r.Quarantined,
            ["remediations"] = r.Remediations,
            ["reviews"] = r.Reviews,
        };
        Assert.Equal(expected.GetProperty("counts").EnumerateObject().Select(c => (c.Name, c.Value.GetInt64())).OrderBy(c => c.Name, StringComparer.Ordinal),
            counts.Where(c => c.Value > 0).Select(c => (c.Key, c.Value)).OrderBy(c => c.Key, StringComparer.Ordinal));
    }

    // ── Observations ─────────────────────────────────────────────────────────

    private static ObservationRecorder Observer() => new("observer-a", new SeedSigner(TestHelpers.ZeroSeedB64, "observer-key-1"));

    private static readonly DateTimeOffset At = new(2026, 10, 30, 12, 0, 0, TimeSpan.Zero);

    private static ObservationInput Seen(string sourceEventId = "e") => new()
    {
        ResourceId = "partner:app-1/secret",
        Action = ResourceActions.Rotate,
        Capability = "partner-secret.rotate",
        ChangedAt = At,
        ObservedAt = At.AddMinutes(1),
        Source = "cloud-activity-log",
        SourceEventId = sourceEventId,
    };

    private static string Json(object record) => JsonSerializer.Serialize(record, Auth.SerializerOptions);

    private static string CanonicalOf(string json) => Canonical.FromJson(json);

    [Fact]
    public async Task AnObservationIsSignedAsTheReferenceSignsIt()
    {
        var record = await Observer().Record(new ObservationInput
        {
            ResourceId = "partner:app-1/secret",
            Action = ResourceActions.Rotate,
            Capability = "partner-secret.rotate",
            ChangedAt = At.AddTicks(1_234_567),
            ObservedAt = At.AddMinutes(5),
            Actor = "principal-7f3a",
            Source = "cloud-activity-log",
            SourceEventId = "event-1",
            VersionId = "v7",
            Metadata = new Dictionary<string, object?> { ["lifetime_days"] = 90, ["ratio"] = 0.5, ["note"] = "café" },
        });
        Assert.Equal(CanonicalOf(Observation), CanonicalOf(Json(record)));
        Assert.Equal(ObservationCanonical, OfflineVerifier.OutOfBandCanonical(Json(record)));
        // The ID is derived from the observer, the source and the source event.
        Assert.Equal(ObservationRecorder.ObservationId("observer-a", "cloud-activity-log", "event-1"), record.ObservationId);
        Assert.Equal(Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes("observer-a\0cloud-activity-log\0event-1"))).ToLowerInvariant(),
            record.ObservationId);
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(Json(record), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(Json(record), ["JUO5L/EJVRFHatyDadtt3JM2ZaEZeN2hQE7hBmypVZ0="]));
    }

    [Fact]
    public async Task AWindowedObservationLeavesAbsentFieldsOutAndRecordsEmptyMetadata()
    {
        var record = await Observer().Record(new ObservationInput
        {
            ObservationId = "obs-window",
            ResourceId = "partner:app-2/secret",
            Action = ResourceActions.Update,
            Capability = "partner-secret.update",
            ChangedNotBefore = At.AddHours(-1),
            ChangedNotAfter = At,
            ObservedAt = At,
            Source = "reconciliation",
            SourceEventId = "scan-1",
        });
        Assert.Equal(CanonicalOf(Window), CanonicalOf(Json(record)));
        var written = JsonNode.Parse(Json(record))!.AsObject();
        Assert.DoesNotContain("changed_at", written.Select(p => p.Key));
        Assert.DoesNotContain("actor", written.Select(p => p.Key));
    }

