    [Fact]
    public async Task AWindowIsOrderedToTheMicrosecond()
    {
        ObservationInput Window(long fromTicks, long toTicks) => new()
        {
            ResourceId = "partner:app-1/secret",
            Action = ResourceActions.Update,
            Capability = "partner-secret.update",
            ChangedNotBefore = At.AddTicks(fromTicks),
            ChangedNotAfter = At.AddTicks(toTicks),
            ObservedAt = At.AddMinutes(1),
            Source = "reconciliation",
            SourceEventId = "w",
        };
        var refused = await Assert.ThrowsAsync<OutOfBandRecordException>(() => Observer().Record(Window(5_000, 1_000)));
        Assert.Equal(("observation_malformed", "changed_not_before is after changed_not_after"), (refused.Code, refused.Detail));
        // Within one microsecond they are the same time as signed.
        Assert.Equal("2026-10-30T12:00:00Z", (await Observer().Record(Window(5, 1))).ChangedNotBefore);
        Assert.NotNull(await Observer().Record(Window(10, 10)));
    }

    [Fact]
    public async Task AnObservationTheNAWouldNotTakeIsRefusedBeforeSigning()
    {
        foreach (var input in new[]
        {
            new ObservationInput { Action = ResourceActions.Rotate, Capability = "c", ChangedAt = At, Source = "s", SourceEventId = "e" },
            new ObservationInput { ResourceId = "r", Action = "rename", Capability = "c", ChangedAt = At, Source = "s", SourceEventId = "e" },
            new ObservationInput { ResourceId = new string('r', 257), Action = ResourceActions.Rotate, Capability = "c", ChangedAt = At, Source = "s", SourceEventId = "e" },
            new ObservationInput { ResourceId = "r", Action = ResourceActions.Rotate, Capability = "c", ChangedAt = At, Source = "s", SourceEventId = "e", Actor = "" },
            new ObservationInput { ResourceId = "r", Action = ResourceActions.Rotate, Capability = "c", ChangedAt = At, Source = new string('s', 129), SourceEventId = "e" },
        })
        {
            await AssertRefused("observation_malformed", "does not match the ObservationRecord model", Observer().Record(input));
        }
        // Lengths are counted in characters (code points), as the reference counts them: 256 emoji are 512 UTF-16 units.
        ObservationInput Named(string resourceId) => new()
        {
            ResourceId = resourceId,
            Action = ResourceActions.Rotate,
            Capability = "c",
            ChangedAt = At,
            Source = "s",
            SourceEventId = "e",
        };
        var emoji = string.Concat(Enumerable.Repeat("🔑", 256));
        Assert.Equal(emoji, (await Observer().Record(Named(emoji))).ResourceId);
        await AssertRefused("observation_malformed", "does not match", Observer().Record(Named(emoji + "🔑")));
    }

    [Fact]
    public async Task SecretMaterialIsRefusedBeforeSigning()
    {
        var observer = Observer();
        var cases = new (Func<ObservationInput, ObservationInput> Change, string Message)[]
        {
            (i => Copy(i, actor: new string('A', 130)), "field 'actor' looks like key or token material"),
            // The reference's `$` matches before a final newline.
            (i => Copy(i, actor: new string('A', 130) + "\n"), "field 'actor' looks like key or token material"),
            (i => Copy(i, sourceEventId: "eyJhbGciOi.eyJzdWIiOi.abc"), "field 'source_event_id' looks like key or token material"),
            (i => Copy(i, versionId: "-----BEGIN X"), "field 'version_id' contains a PEM block"),
            (i => Copy(i, metadata: new() { ["Client_Secret"] = "x" }), "field 'metadata.Client_Secret' is not allowed in evidence metadata"),
        };
        foreach (var (change, message) in cases)
        {
            var refused = await Assert.ThrowsAsync<OutOfBandRecordException>(() => observer.Record(change(Seen())));
            Assert.Equal(("observation_secret_material", message), (refused.Code, refused.Detail));
        }
        var large = await Assert.ThrowsAsync<OutOfBandRecordException>(() =>
            observer.Record(Copy(Seen(), metadata: new() { ["note"] = new string('é', 3000) })));
        Assert.Equal("observation_secret_material", large.Code);
        Assert.Contains("over the 16384-byte limit", large.Detail, StringComparison.Ordinal);
    }

    [Fact]
    public async Task AValueTheNACouldNotReadIsRefusedBeforeSigning()
    {
        await Assert.ThrowsAsync<StrictJsonException>(() =>
            Observer().Record(Copy(Seen(), metadata: new() { ["s"] = "\ud83d" })));
        await Assert.ThrowsAsync<StrictJsonException>(() =>
            Observer().Record(Copy(Seen(), metadata: new() { ["n"] = decimal.MaxValue })));
    }

    [Fact]
    public async Task AnObservationIsRefusedInTheNAsOrder()
    {
        // A value the NA could not read, before the change times its model checks.
        await Assert.ThrowsAsync<StrictJsonException>(() => Observer().Record(new ObservationInput
        {
            ResourceId = "r",
            Action = ResourceActions.Rotate,
            Capability = "c",
            ChangedAt = At,
            ChangedNotBefore = At.AddHours(-1),
            ChangedNotAfter = At,
            Source = "s",
            SourceEventId = "e",
            Metadata = new Dictionary<string, object?> { ["s"] = "\ud83d" },
        }));
        // A record the model does not take, before secret material.
        await AssertRefused("observation_malformed", "does not match", Observer().Record(Copy(Seen(), actor: "", versionId: "-----BEGIN X")));
        // A window with equal ends is in order: what the model does not take is another field.
        await AssertRefused("observation_malformed", "does not match the ObservationRecord model", Observer().Record(new ObservationInput
        {
            Action = ResourceActions.Rotate,
            Capability = "c",
            ChangedNotBefore = At,
            ChangedNotAfter = At,
            Source = "s",
            SourceEventId = "e",
        }));
        // A missing source or source event is a field the model does not take, as a missing resource is.
        foreach (var (source, sourceEventId) in new (string, string)[] { (null!, "e"), ("s", null!) })
        {
            await AssertRefused("observation_malformed", "does not match", Observer().Record(new ObservationInput
            {
                ResourceId = "r",
                Action = ResourceActions.Rotate,
                Capability = "c",
                ChangedAt = At,
                Source = source,
                SourceEventId = sourceEventId,
            }));
        }
        // An ID of at most 128 characters.
        Assert.NotNull(await Observer().Record(Copy(Seen(), observationId: new string('o', 128))));
        await AssertRefused("observation_malformed", "does not match", Observer().Record(Copy(Seen(), observationId: new string('o', 129))));
    }

    [Fact]
    public async Task AnObservationIdTheCallerGivesIsKept()
    {
        Assert.Equal("mine", (await Observer().Record(Copy(Seen(), observationId: "mine"))).ObservationId);
        Assert.Equal(ObservationRecorder.ObservationId("observer-a", "cloud-activity-log", "e"), (await Observer().Record(Seen())).ObservationId);
    }

