    [Fact]
    public void ARecorderNeedsAnObserverAndASigner()
    {
        Assert.Throws<ArgumentException>(() => new ObservationRecorder("", new SeedSigner(TestHelpers.ZeroSeedB64, "k")));
        Assert.Throws<ArgumentNullException>(() => new ObservationRecorder("o", null!));
        var recorder = new ObservationRecorder("o", new SeedSigner(TestHelpers.ZeroSeedB64, "k"));
        Assert.Equal(("o", "k"), (recorder.ObserverSovereignId, recorder.KeyId));
    }

    private static ObservationInput Copy(
        ObservationInput i, string? actor = null, string? sourceEventId = null, string? versionId = null,
        Dictionary<string, object?>? metadata = null, string? observationId = null, bool observedAtNow = false) => new()
        {
            ResourceId = i.ResourceId,
            Action = i.Action,
            Capability = i.Capability,
            ChangedAt = i.ChangedAt,
            ObservedAt = observedAtNow ? null : i.ObservedAt,
            Actor = actor ?? i.Actor,
            Source = i.Source,
            SourceEventId = sourceEventId ?? i.SourceEventId,
            VersionId = versionId ?? i.VersionId,
            Metadata = metadata ?? i.Metadata,
            ObservationId = observationId ?? i.ObservationId,
        };

    private static async Task AssertRefused(string code, string detail, Task task)
    {
        var refused = await Assert.ThrowsAsync<OutOfBandRecordException>(() => task);
        Assert.Equal(code, refused.Code);
        Assert.Contains(detail, refused.Detail, StringComparison.Ordinal);
        Assert.Equal(0, refused.Status);
    }

    // ── Reconciliation findings ──────────────────────────────────────────────

    private static readonly ReconciliationFinding Drifted = new()
    {
        ResourceId = "kv:prod/api-key",
        Status = ReconciliationStatuses.Drifted,
        Detail = "cloud version 3, governed version 2",
        Observed = new ObservedResource
        {
            ResourceId = "kv:prod/api-key",
            Exists = true,
            Version = "3",
            Metadata = new Dictionary<string, object?> { ["vault"] = "prod" },
        },
    };

    private static readonly FindingObservationOptions Scan = new()
    {
        Capability = "secret.rotate",
        PreviousScanAt = new DateTimeOffset(2026, 1, 1, 0, 0, 0, TimeSpan.Zero),
        ScannedAt = new DateTimeOffset(2026, 1, 1, 1, 0, 0, TimeSpan.Zero),
    };

    [Fact]
    public async Task AFindingIsAWindowedObservationOncePerScan()
    {
        var input = ObservationRecorder.FromFinding(Drifted, Scan)!;
        Assert.Equal((ResourceActions.Update, "reconciliation", "3"), (input.Action, input.Source, input.VersionId));
        Assert.Equal((Scan.PreviousScanAt, Scan.ScannedAt, Scan.ScannedAt), (input.ChangedNotBefore!.Value, input.ChangedNotAfter!.Value, input.ObservedAt!.Value));
        Assert.Null(input.ChangedAt);
        Assert.Equal(Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes("2026-01-01T01:00:00Z\0kv:prod/api-key\0drifted"))).ToLowerInvariant(),
            input.SourceEventId);
        Assert.Equal(new Dictionary<string, object?> { ["status"] = "drifted", ["vault"] = "prod" }, input.Metadata);

        // Signed again, a repeated scan's finding is the same record.
        var first = await Observer().Record(input);
        Assert.Equal(Json(first), Json(await Observer().Record(ObservationRecorder.FromFinding(Drifted, Scan)!)));
    }

    [Fact]
    public void AFindingsActionComesFromItsStatus()
    {
        string? Action(string status, FindingObservationOptions? options = null) =>
            ObservationRecorder.FromFinding(new ReconciliationFinding { ResourceId = "r", Status = status }, options ?? Scan)?.Action;
        Assert.Equal(ResourceActions.Create, Action(ReconciliationStatuses.Unmanaged));
        Assert.Equal(ResourceActions.Update, Action(ReconciliationStatuses.PresentAfterRevoke));
        Assert.Equal(ResourceActions.Delete, Action(ReconciliationStatuses.Missing));
        Assert.Null(Action(ReconciliationStatuses.InSync));
        var options = new FindingObservationOptions
        {
            Capability = "c",
            PreviousScanAt = Scan.PreviousScanAt,
            ScannedAt = Scan.ScannedAt,
            Source = "scan",
            Actions = new Dictionary<string, string> { [ReconciliationStatuses.Missing] = ResourceActions.Revoke },
        };
        Assert.Equal(ResourceActions.Revoke, Action(ReconciliationStatuses.Missing, options));
        Assert.Equal(ResourceActions.Create, Action(ReconciliationStatuses.Unmanaged, options));
        Assert.Equal("scan", ObservationRecorder.FromFinding(new ReconciliationFinding { ResourceId = "r", Status = "missing" }, options)!.Source);
        // A finding without an observed resource has no version and only its status as metadata.
        var bare = ObservationRecorder.FromFinding(new ReconciliationFinding { ResourceId = "r", Status = "missing" }, Scan)!;
        Assert.Null(bare.VersionId);
        Assert.Equal(new Dictionary<string, object?> { ["status"] = "missing" }, bare.Metadata);
        Assert.Throws<ArgumentNullException>(() => ObservationRecorder.FromFinding(null!, Scan));
        Assert.Throws<ArgumentNullException>(() => ObservationRecorder.FromFinding(Drifted, null!));
    }

    [Fact]
    public void AFindingsOwnMetadataIsKept_AndBothScanTimesAreRequired()
    {
        var finding = new ReconciliationFinding
        {
            ResourceId = "r",
            Status = ReconciliationStatuses.Drifted,
            Observed = new ObservedResource { ResourceId = "r", Exists = true, Metadata = new Dictionary<string, object?> { ["status"] = "enabled" } },
        };
        Assert.Equal(new Dictionary<string, object?> { ["status"] = "enabled" }, ObservationRecorder.FromFinding(finding, Scan)!.Metadata);
        foreach (var options in new[]
        {
            new FindingObservationOptions { Capability = "c", ScannedAt = Scan.ScannedAt },
            new FindingObservationOptions { Capability = "c", PreviousScanAt = Scan.PreviousScanAt },
        })
        {
            Assert.Throws<ArgumentException>(() => ObservationRecorder.FromFinding(finding, options));
            Assert.Throws<ArgumentException>(() => ObservationRecorder.FromFinding(new ReconciliationFinding { ResourceId = "r", Status = ReconciliationStatuses.InSync }, options));
        }
    }

