            EvaluationRequest = FailedRequest,
            EvaluationFailure = failure,
            ExecutedAt = At.AddSeconds(1),
            Outcome = outcome,
            OutcomeDetail = outcomeDetail,
            ExecutionParameters = new Dictionary<string, object?> { ["secret_version"] = "v8" },
        };

    [Fact]
    public async Task ABreakGlassRecordIsSignedAsTheReferenceSignsIt()
    {
        // Its ID is new each time; given the reference's, the record and its signature are the reference's.
        var record = OutOfBandRecords.BreakGlass(Glass(), "executor-a");
        record.BreakGlassId = "00000000-0000-4000-8000-0000000000b1";
        var unsigned = OutOfBandRecords.CheckBreakGlass(record);
        Assert.Equal(BreakGlassCanonical, OfflineVerifier.OutOfBandCanonical(unsigned));
        record.Signature = await OutOfBandRecords.Sign(unsigned, new SeedSigner(TestHelpers.ZeroSeedB64, "executor-key-1"), default);
        Assert.Equal(CanonicalOf(BreakGlass), CanonicalOf(Json(record)));

        var signed = await Executor().SignBreakGlass(Glass());
        Assert.True(Guid.TryParse(signed.BreakGlassId, out _));
        Assert.Equal("a36b6403d4d7e6bc27d8bbe5af54f14324c569334550bbeb2e2eb8d443128ab9", signed.EvaluationRequestDigest);
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(Json(signed), [PublicKey]));
        Assert.DoesNotContain("outcome_detail", JsonNode.Parse(Json(signed))!.AsObject().Select(p => p.Key));
    }

    [Fact]
    public async Task ABreakGlassRecordNeedsAJustificationOfAtMost1024Characters()
    {
        await AssertRefused("break_glass_malformed", "a justification of 1 to 1024 characters is required", Executor().SignBreakGlass(Glass(justification: "")));
        // 1020 characters, 1040 UTF-16 units.
        var emoji = string.Concat(Enumerable.Repeat("Rotate the leaked key now. ", 38))[..1000] + string.Concat(Enumerable.Repeat("🚨", 20));
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(Json(await Executor().SignBreakGlass(Glass(justification: emoji))), [PublicKey]));
        await AssertRefused("break_glass_malformed", "a justification of 1 to 1024 characters is required",
            Executor().SignBreakGlass(Glass(justification: new string('x', 1005) + string.Concat(Enumerable.Repeat("🚨", 20)))));
        await AssertRefused("break_glass_malformed", "outcome_detail is longer than 1024 characters",
            Executor().SignBreakGlass(Glass(outcomeDetail: new string('é', 1025))));
        Assert.Equal(new string('é', 1024), (await Executor().SignBreakGlass(Glass(outcomeDetail: new string('é', 1024)))).OutcomeDetail);
        await AssertRefused("break_glass_malformed", "a justification", Executor().SignBreakGlass(new BreakGlassInput
        {
            ResourceId = "r",
            ResourceAction = "rotate",
            Capability = "c",
            Justification = null!,
            EvaluationRequest = FailedRequest,
            EvaluationFailure = EvaluationFailures.Timeout,
            Outcome = "success",
        }));
    }

