    private static JsonElement Values(object values) => JsonSerializer.SerializeToElement(values);

    [Fact]
    public void TheGuardSizesValuesAsEscapedCanonicalJson()
    {
        // Python: metadata_problem({'metadata': {'note': 'é' * 3000}}): 6027 bytes as UTF-8, 18024 escaped.
        Assert.Equal("metadata is 18024 bytes, over the 16384-byte limit",
            EvidenceMetadata.MetadataProblem(Values(new { metadata = new { note = new string('é', 3000) } })));
        // An emoji is a surrogate pair: 12 bytes escaped.
        Assert.Equal("metadata is 16404 bytes, over the 16384-byte limit",
            EvidenceMetadata.MetadataProblem(Values(new { metadata = new { note = string.Concat(Enumerable.Repeat("😀 ", 1260)) } })));
        Assert.Null(EvidenceMetadata.MetadataProblem(Values(new { metadata = new { note = string.Concat(Enumerable.Repeat("😀 ", 1250)) } })));
    }

    [Fact]
    public void TheGuardChecksValueByValueInTheOrderGiven()
    {
        using var doc = JsonDocument.Parse("""{"b":"-----BEGIN","a":{"token":"t"},"password":"x"}""");
        Assert.Equal("field 'b' contains a PEM block", EvidenceMetadata.MetadataProblem(doc.RootElement));
        using var named = JsonDocument.Parse("""{"note":"ok","Pass_Word":3,"list":["fine",{"api-key":1}]}""");
        Assert.Equal("field 'Pass_Word' is not allowed in evidence metadata", EvidenceMetadata.MetadataProblem(named.RootElement));
        using var nested = JsonDocument.Parse("""{"note":"ok","list":["fine",{"api-key":1}]}""");
        Assert.Equal("field 'list.1.api-key' is not allowed in evidence metadata", EvidenceMetadata.MetadataProblem(nested.RootElement));
        using var clean = JsonDocument.Parse("""{"n":1,"f":0.5,"t":true,"z":null,"s":"text"}""");
        Assert.Null(EvidenceMetadata.MetadataProblem(clean.RootElement));
        Assert.Throws<ArgumentException>(() => EvidenceMetadata.MetadataProblem(Values(new[] { 1 })));
        Assert.Throws<ArgumentNullException>(() => EvidenceMetadata.ObservationProblem(null!));
        Assert.Throws<ArgumentNullException>(() => EvidenceMetadata.BreakGlassProblem(null!));
    }

