    private static string Record(string id) => Vector(id).GetProperty("record").GetRawText();

    private const string NaKey = "JUO5L/EJVRFHatyDadtt3JM2ZaEZeN2hQE7hBmypVZ0=";

    [Fact]
    public void AnNARecordIsVerifiedUnderTheKeyValidAtItsSignedTime()
    {
        var judgement = Record("signature-judgement-na-key");
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(judgement, NAKeyHistory.ValidAlways([NaKey])));
        var judgedAt = new DateTimeOffset(2026, 1, 1, 0, 8, 0, TimeSpan.Zero);
        NAKeyHistory Valid(DateTimeOffset from, DateTimeOffset? to) =>
            new("sovereign-c", null, [new NAKey(1, "na-key", NaKey, from, null, to, true)]);
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(judgement, Valid(judgedAt.AddDays(-1), judgedAt.AddDays(1))));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(judgement, Valid(judgedAt.AddMinutes(1), null)));
        // An observation, which the NA does not sign, is checked under any key of a history, whatever its time.
        var later = new NAKeyHistory("sovereign-c", null, [new NAKey(1, "observer-key-1", PublicKey, judgedAt.AddYears(5), null, null, false)]);
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(Observation, later));
        Assert.Throws<ArgumentNullException>(() => OfflineVerifier.VerifyOutOfBandRecord(Observation, (NAKeyHistory)null!));
        Assert.Throws<ArgumentNullException>(() => OfflineVerifier.VerifyOutOfBandRecord(Observation, (IReadOnlyList<string>)null!));
    }

    [Fact]
    public async Task ARecordIsVerifiedOnlyAsItsKindAndForm()
    {
        // Signed again after the change, so what refuses it is the kind, the shape or the form.
        async Task<bool> Verify(Action<JsonObject> change, string json = Observation) =>
            OfflineVerifier.VerifyOutOfBandRecord(await Resign(json, change), [PublicKey]);
        bool Unsigned(Action<JsonObject> change)
        {
            var record = JsonNode.Parse(Observation)!.AsObject();
            change(record);
            return OfflineVerifier.VerifyOutOfBandRecord(record.ToJsonString(), [PublicKey]);
        }
        Assert.True(await Verify(_ => { }));
        Assert.False(await Verify(r => r["actor_note"] = "x"));                                      // a field this SDK does not know
        Assert.False(Unsigned(r => r.Remove("signature")));
        Assert.False(Unsigned(r => r["signature"] = null));
        Assert.False(Unsigned(r => r["signature"] = new JsonObject { ["key_id"] = "k" }));
        Assert.False(Unsigned(r => r["actor"] = "principal-other"));                                // changed after signing
        Assert.False(await Verify(r => r["changed_at"] = "2026-10-30T12:00:00.123456"));            // not UTC
        Assert.False(await Verify(r => r["changed_not_after"] = "2026-10-30T13:00:00Z"));          // a time and a window
        Assert.False(await Verify(r => { r.Remove("observation_id"); r["remediation_id"] = "x"; })); // a kind of a later release
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord("[1]", [PublicKey]));
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(BreakGlass, [PublicKey]));
        Assert.True(await Verify(_ => { }, BreakGlass));
        Assert.False(await Verify(r => r["evaluation_request_digest"] = "ab", BreakGlass));
        Assert.False(await Verify(r => r["evaluation_request_digest"] = new string('a', 65), BreakGlass));
        Assert.False(await Verify(r => r["evaluation_failure"] = "deny", BreakGlass));
        Assert.Throws<StrictJsonException>(() => OfflineVerifier.VerifyOutOfBandRecord("{\"a\":1,\"a\":2}", [PublicKey]));
    }

    [Fact]
    public async Task AnOptionalNullIsLeftOutOfTheSignedFormAndAFilledFieldMustBeThere()
    {
        // Signed without metadata, which the reference fills: not in its form.
        var signer = new SeedSigner(TestHelpers.ZeroSeedB64, "observer-key-1");
        var record = JsonNode.Parse(Window)!.AsObject();
        record.Remove("metadata");
        record.Remove("signature");
        using (var doc = JsonDocument.Parse(record.ToJsonString()))
            record["signature"] = JsonNode.Parse((await OutOfBandRecords.Sign(doc.RootElement, signer, default)).GetRawText());
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(record.ToJsonString(), [PublicKey]));

        // A null optional field is left out of the signed form, as absent.
        var withNull = JsonNode.Parse(Window)!.AsObject();
        withNull["actor"] = null;
        Assert.Equal(OfflineVerifier.OutOfBandCanonical(Window), OfflineVerifier.OutOfBandCanonical(withNull.ToJsonString()));
        Assert.True(OfflineVerifier.VerifyOutOfBandRecord(withNull.ToJsonString(), [PublicKey]));
        Assert.Throws<ArgumentException>(() => OfflineVerifier.OutOfBandCanonical("[]"));
        Assert.Throws<ArgumentException>(() => OfflineVerifier.OutOfBandDigest("\"x\""));
    }

    /// <summary>A vector's record signed again by the zero seed, after <paramref name="change"/>.</summary>
    private static Task<string> Resigned(string id, Action<JsonObject>? change = null) => Resign(Record(id), change);

    /// <summary>A record signed again by the zero seed, after <paramref name="change"/>.</summary>
    private static async Task<string> Resign(string json, Action<JsonObject>? change = null)
    {
        var record = JsonNode.Parse(json)!.AsObject();
        change?.Invoke(record);
        record.Remove("signature");
        using var doc = JsonDocument.Parse(record.ToJsonString());
        record["signature"] = JsonNode.Parse((await OutOfBandRecords.Sign(doc.RootElement,
            new SeedSigner(TestHelpers.ZeroSeedB64, "na-key"), default)).GetRawText());
        return record.ToJsonString();
    }

