    {
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-quarantine", r => r["record_kind"] = "decision"), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-quarantine", r => r["record_digest"] = "ab"), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-registry", r => r["event"] = "policy_renamed"), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-registry", r => r["policy_version"] = 0), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-judgement", r => r["verdict"] = "maybe"), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-judgement", r => r["subject_store_sequence"] = 0), [PublicKey]));
        // A UTC offset other than Z is the right instant, but not the reference's form.
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-registry", r => r["effective_at"] = "2026-01-01T00:00:00+00:00"), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-registry", r => r["effective_at"] = "2026-01-01T00:00:00-00:00"), [PublicKey]));
        Assert.False(OfflineVerifier.VerifyOutOfBandRecord(await Resigned("canonical-registry", r => r["effective_at"] = "2026-01-01T01:00:00+01:00"), [PublicKey]));
