    private sealed class ShortSigner : ISigner
    {
        public string KeyId => "short";

        public ValueTask<byte[]> SignAsync(ReadOnlyMemory<byte> message, CancellationToken cancellationToken = default) =>
            ValueTask.FromResult(new byte[63]);
    }

    [Theory]
    [InlineData("canonical-observation", typeof(ObservationRecord))]
