    [InlineData("canonical-quarantine", typeof(QuarantineRecord))]
    [InlineData("canonical-registry", typeof(RegistryRecord))]
    public void ATypedRecordKeepsItsSignedForm(string id, Type model)
    {
        var raw = Record(id);
        var typed = JsonSerializer.Deserialize(raw, model, Auth.SerializerOptions)!;
        var written = JsonSerializer.Serialize(typed, model, Auth.SerializerOptions);
        Assert.Equal(CanonicalOf(raw), CanonicalOf(written));
