    // ── The store calls ──────────────────────────────────────────────────────

    private sealed record Sent(string Method, string Path, string? Body, bool Admin);

    private static HttpResponseMessage Answer(int status, string body) =>
        new((HttpStatusCode)status) { Content = new StringContent(body, Encoding.UTF8, "application/json") };

    private static HttpResponseMessage Refused(int status, string code) =>
        Answer(status, new JsonObject { ["error"] = new JsonObject { ["code"] = code, ["message"] = "refused" } }.ToJsonString());

    private static GenesisMeshClient Client(List<Sent> sent, Func<HttpRequestMessage, HttpResponseMessage> answer, int retries = 0) =>
        new(new ClientOptions
        {
            BaseUrl = "http://localhost",
            SigningKey = TestHelpers.ZeroSeedB64,
            KeyId = "ops",
            Audience = "TEST",
            Retry = new RetrySettings { Attempts = retries, BaseDelay = TimeSpan.Zero },
            HttpHandler = new FuncHandler(req =>
            {
                sent.Add(new Sent(req.Method.Method, Uri.UnescapeDataString(req.RequestUri!.PathAndQuery),
                    req.Content?.ReadAsStringAsync().Result, req.Headers.Contains("X-Admin-Key-Id")));
                return answer(req);
            }),
        });

    private const string Envelope = """{"store_sequence":4,"entry_kind":"observation","recorded_at":"2026-10-30T12:06:00Z","payload_digest":"00","prev_entry_digest":"11","decision_id":null,"context_id":null,"vendor_id":null,"attestation_id":null,"capability":"partner-secret.rotate","outcome":null,"evidence_id":null,"executor_sovereign_id":null,"exec_sequence_no":null,"resource_id":"partner:app-1/secret","resource_action":"rotate","resource_sequence":null,"record_id":"obs-1","observation_sequence":1}""";

    private static string Judged(string status = "judged") =>
        $$"""{"status":"{{status}}","entry":{{Envelope}},"entry_digest":"22","payload":{{Record("signature-judgement-na-key")}}}""";

    [Fact]
    public async Task SubmitObservation_IsPublicAndRetried_AndReadsTheJudgementMadeAtAdmission()
    {
        var sent = new List<Sent>();
        var calls = 0;
        using var gm = Client(sent, _ => ++calls == 1
            ? Refused(503, "unavailable")
            : Answer(201, $$$"""{"status":"recorded","entry":{{{Envelope}}},"entry_digest":"33","payload":{{{Observation}}},"judgement":{{{Judged()}}}}"""), retries: 1);
        var observation = JsonSerializer.Deserialize<ObservationRecord>(Observation, Auth.SerializerOptions)!;
        var result = await gm.EvidenceStore.SubmitObservation(observation);
        Assert.Equal(("recorded", 4L, "33"), (result.Status, result.Entry.StoreSequence, result.EntryDigest));
        Assert.Equal(("judged", "deny", "after_the_fact"), (result.Judgement!.Status, result.Judgement.Payload.Verdict, result.Judgement.Payload.GovernedBy));
        Assert.Equal("obs-1", result.Entry.RecordId);
        Assert.Equal(2, sent.Count);
        Assert.Equal(("POST", "/evidence/observations", false), (sent[1].Method, sent[1].Path, sent[1].Admin));
        var body = JsonNode.Parse(sent[1].Body!)!.AsObject();
        Assert.Equal(CanonicalOf(Observation), CanonicalOf(body["observation"]!.ToJsonString()));
        await Assert.ThrowsAsync<ArgumentNullException>(() => gm.EvidenceStore.SubmitObservation(null!));
    }

    [Fact]
    public async Task SubmitObservation_ReadsADuplicateWithoutAJudgement_AndARefusalWithItsCode()
    {
        var sent = new List<Sent>();
        var answer = Answer(200, $$"""{"status":"duplicate","entry":{{Envelope}},"entry_digest":"33","payload":{{Observation}}}""");
        using var gm = Client(sent, _ => answer);
        var observation = JsonSerializer.Deserialize<ObservationRecord>(Observation, Auth.SerializerOptions)!;
        var duplicate = await gm.EvidenceStore.SubmitObservation(observation);
        Assert.Equal("duplicate", duplicate.Status);
        Assert.Null(duplicate.Judgement);
        answer = Refused(422, "observation_out_of_scope");
        var refused = await Assert.ThrowsAsync<ValidationException>(() => gm.EvidenceStore.SubmitObservation(observation));
        Assert.Equal("observation_out_of_scope", refused.Code);
        answer = Refused(409, "observation_conflict");
        Assert.Equal("observation_conflict",
            (await Assert.ThrowsAsync<ConflictException>(() => gm.EvidenceStore.SubmitObservation(observation))).Code);
    }

    [Fact]
    public async Task SubmitObservations_SendsABatchAndReadsEachAnswerByIndex()
    {
        var sent = new List<Sent>();
        using var gm = Client(sent, _ => Answer(200, $$$"""
            {"results":[
              {"index":0,"status":"recorded","entry":{{{Envelope}}},"entry_digest":"33","payload":{{{Observation}}},"judgement":null},
              {"index":1,"status":"refused","error":{"code":"observation_invalid_signature","message":"signature does not verify","details":{"quarantine_id":"q-1"} } }
            ]}
            """));
        var observation = JsonSerializer.Deserialize<ObservationRecord>(Observation, Auth.SerializerOptions)!;
        var results = await gm.EvidenceStore.SubmitObservations([observation, observation]);
        Assert.Equal(("/evidence/observations/batch", false), (sent[0].Path, sent[0].Admin));
        Assert.Equal(2, JsonNode.Parse(sent[0].Body!)!["observations"]!.AsArray().Count);
        Assert.Equal((0, "recorded", "33"), (results[0].Index, results[0].Status, results[0].EntryDigest));
        Assert.Null(results[0].Judgement);
        Assert.Null(results[0].Error);
        Assert.Equal((1, "refused"), (results[1].Index, results[1].Status));
        Assert.Null(results[1].Entry);
        Assert.Equal(JsonValueKind.Undefined, results[1].Payload.ValueKind);
        Assert.Equal(("observation_invalid_signature", "signature does not verify", "q-1"),
            (results[1].Error!.Code, results[1].Error!.Message, results[1].Error!.Details.GetProperty("quarantine_id").GetString()));

        await Assert.ThrowsAsync<ArgumentException>(() => gm.EvidenceStore.SubmitObservations([]));
        await Assert.ThrowsAsync<ArgumentException>(() => gm.EvidenceStore.SubmitObservations(Enumerable.Repeat(observation, 101).ToList()));
        await Assert.ThrowsAsync<ArgumentNullException>(() => gm.EvidenceStore.SubmitObservations(null!));
        Assert.Single(sent);
        using var full = Client(sent, _ => Answer(200, """{"results":[]}"""));
        Assert.Empty(await full.EvidenceStore.SubmitObservations(Enumerable.Repeat(observation, 100).ToList()));
    }

