    private static string ChangesPage(string changes, bool truncated, long? next) =>
        $$"""{"resource_id":"kv:prod/a b","truncated":{{(truncated ? "true" : "false")}},"changes":[{{changes}}],"next_after_sequence":{{(next is { } n ? n.ToString(System.Globalization.CultureInfo.InvariantCulture) : "null")}}}""";

    private const string ObservedChange = """{"store_sequence":4,"kind":"observation","recorded_at":"2026-10-30T12:06:00+00:00","record_id":"obs-1","action":"rotate","at":"2026-10-30T12:00:00Z","governed_by":"after_the_fact","state":"judged_denied","verdict":"deny","flagged_for_review":true,"possible_match_evidence_id":"ev-9"}""";
    private const string QuarantinedChange = """{"store_sequence":7,"kind":"quarantine","recorded_at":"2026-10-30T12:07:00+00:00","record_id":"q-1","action":null,"at":"2026-10-30T12:07:00Z","governed_by":null,"state":"quarantined","record_kind":"observation","rejection_code":"observation_outside_time_bounds"}""";

    [Fact]
    public async Task ResourceChanges_ReadsAPage()
    {
        var sent = new List<Sent>();
        using var gm = Client(sent, _ => Answer(200, ChangesPage(ObservedChange + "," + QuarantinedChange, true, 7)));
        var page = await gm.EvidenceStore.ResourceChanges("kv:prod/a b", new ResourceChangesParams { Limit = 2, AfterSequence = 3 });
        Assert.Equal(("GET", "/admin/evidence/changes/kv:prod/a b?limit=2&after_sequence=3", true), (sent[0].Method, sent[0].Path, sent[0].Admin));
        Assert.Equal(("kv:prod/a b", true, 7L), (page.ResourceId, page.Truncated, page.NextAfterSequence));
        var observed = page.Changes[0];
        Assert.Equal(("observation", "judged_denied", "deny", true, "ev-9"),
            (observed.Kind, observed.State, observed.Verdict, observed.FlaggedForReview, observed.PossibleMatchEvidenceId));
        var quarantined = page.Changes[1];
        Assert.Equal(("quarantine", null, null, "observation", "observation_outside_time_bounds"),
            (quarantined.Kind, quarantined.Action, quarantined.GovernedBy, quarantined.RecordKind, quarantined.RejectionCode));
        await gm.EvidenceStore.ResourceChanges("r");
        Assert.Equal("/admin/evidence/changes/r", sent[1].Path);
    }

    [Theory]
    [InlineData(0, null)]
    [InlineData(10_001, null)]
    [InlineData(null, -1L)]
    public async Task ResourceChanges_RefusesAPageOutOfRange(int? limit, long? after)
    {
        var sent = new List<Sent>();
        using var gm = Client(sent, _ => Answer(200, ChangesPage("", false, null)));
        await Assert.ThrowsAsync<ArgumentOutOfRangeException>(() =>
            gm.EvidenceStore.ResourceChanges("r", new ResourceChangesParams { Limit = limit, AfterSequence = after }));
        if (after is null) Assert.Throws<ArgumentOutOfRangeException>(() => gm.EvidenceStore.AllResourceChanges("r", limit));
        Assert.Throws<ArgumentException>(() => gm.EvidenceStore.AllResourceChanges("r/../x"));
        await Assert.ThrowsAsync<ArgumentException>(() => gm.EvidenceStore.ResourceChanges(""));
        Assert.Empty(sent);
        await gm.EvidenceStore.ResourceChanges("r", new ResourceChangesParams { Limit = 10_000, AfterSequence = 0 });
        Assert.Equal("/admin/evidence/changes/r?limit=10000&after_sequence=0", sent[0].Path);
    }

    [Fact]
    public async Task AllResourceChanges_FollowsThePages()
    {
        var sent = new List<Sent>();
        using var gm = Client(sent, req => Answer(200, req.RequestUri!.Query.Contains("after_sequence=4", StringComparison.Ordinal)
            ? ChangesPage(QuarantinedChange, false, null)
            : ChangesPage(ObservedChange, true, 4)));
        var changes = new List<ResourceChange>();
        await foreach (var c in gm.EvidenceStore.AllResourceChanges("kv:prod/a b", limit: 1)) changes.Add(c);
        Assert.Equal([4L, 7L], changes.Select(c => c.StoreSequence));
        Assert.Equal(["/admin/evidence/changes/kv:prod/a b?limit=1", "/admin/evidence/changes/kv:prod/a b?limit=1&after_sequence=4"],
            sent.Select(s => s.Path));
    }

    [Fact]
    public async Task AllResourceChanges_RefusesACursorThatDoesNotAdvance_AndATruncatedPageWithoutOne()
    {
        // A cursor that stays or goes back; the third page would end the changes, so a cursor taken is no loop.
        foreach (var second in new long[] { 4, 3 })
        {
            var pages = 0;
            using var stuck = Client([], _ => (++pages) switch
            {
                1 => Answer(200, ChangesPage(ObservedChange, true, 4)),
                2 => Answer(200, ChangesPage(ObservedChange, true, second)),
                _ => Answer(200, ChangesPage("", false, null)),
            });
            var refused = await Assert.ThrowsAsync<InvalidOperationException>(async () =>
            {
                await foreach (var _ in stuck.EvidenceStore.AllResourceChanges("r")) { }
            });
            Assert.Contains("did not advance", refused.Message, StringComparison.Ordinal);
            Assert.Equal(2, pages);
        }
        using var old = Client([], _ => Answer(200, """{"resource_id":"r","truncated":true,"changes":[]}"""));
        var error = await Assert.ThrowsAsync<InvalidOperationException>(async () =>
        {
            await foreach (var _ in old.EvidenceStore.AllResourceChanges("r")) { }
        });
        Assert.Contains("upgrade the NA", error.Message, StringComparison.Ordinal);
        using var single = Client([], _ => Answer(200, """{"resource_id":"r","truncated":false,"changes":[]}"""));
        await foreach (var _ in single.EvidenceStore.AllResourceChanges("r")) Assert.Fail("no changes");
    }

    [Fact]
    public async Task OperatorHolders_AreReadAndChangedByTwoHolders()
    {
        var sent = new List<Sent>();
        using var gm = Client(sent, req => req.RequestUri!.AbsolutePath switch
        {
            "/admin/evidence/operator-holders" => Answer(200, """{"holders":[{"key_id":"ops","holder":"holder-a","public_key":"pk","operator_tier":"privileged","since":"2026-10-30T12:00:00+00:00","approved_by":null,"registry_record_id":"r-1"}]}"""),
            "/admin/operator-keys/controller/holder" => Answer(201, """{"proposal_id":"p-1","key_id":"controller","holder":"holder-c","proposed_by":"ops","approved":false}"""),
            _ => Answer(200, """{"proposal_id":"p-1","key_id":"controller","holder":"holder-c","approved":true,"approved_by":"ops2","registry_record_id":"r-2"}"""),
        });
        var holders = await gm.EvidenceStore.OperatorHolders();
        Assert.Equal(("ops", "holder-a", "privileged", null), (holders[0].KeyId, holders[0].Holder, holders[0].OperatorTier, holders[0].ApprovedBy));
        var proposal = await gm.EvidenceStore.ProposeHolder("controller", "holder-c");
        Assert.Equal(("p-1", "ops", false), (proposal.ProposalId, proposal.ProposedBy, proposal.Approved));
        var approval = await gm.EvidenceStore.ApproveHolder("p-1");
        Assert.Equal((true, "ops2", "r-2"), (approval.Approved, approval.ApprovedBy, approval.RegistryRecordId));
        Assert.Equal(
            [("GET", "/admin/evidence/operator-holders", null, true), ("POST", "/admin/operator-keys/controller/holder", """{"holder":"holder-c"}""", true),
             ("POST", "/admin/operator-keys/holder-changes/p-1/approve", "{}", true)],
            sent.Select(s => (s.Method, s.Path, s.Body, s.Admin)));
        await Assert.ThrowsAsync<ArgumentNullException>(() => gm.EvidenceStore.ProposeHolder("ops", null!));
    }

